# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
POOL_DIR = ROOT / "casmi26-scratch-pool"
VAL_DIR = ROOT / "val_scripts"
OUT = ROOT / "_r3_audit"
WORKERS = os.cpu_count() or 2
BANKS = {"own": (ROOT / "casmi-fpnet", [ROOT / "coconut_dataset"]),
         "ahmed": (ROOT / "casmi26-fpnet-full1", [ROOT / "casmi26-v2-pool"])}
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
OUT.mkdir(parents=True, exist_ok=True)

RDKIT_PIN = "2026.03.3"
r_ = subprocess.run([sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}"], capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("rdkit install failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__

import numpy as np  # noqa: E402
import torch  # noqa: E402

from casmi_scratch import audit, fpnet  # noqa: E402
from casmi_scratch.config import Config  # noqa: E402
from casmi_scratch.library import load_library, remap_keys  # noqa: E402
from casmi_scratch.pool import load_keymap, load_pool  # noqa: E402

CFG = Config().with_(frag_workers=WORKERS)
T0 = time.time()
print(f"torch {torch.__version__} cuda {torch.cuda.is_available()}")


def find(name):
    for depth in ("*", "*/*", "*/*/*"):
        hits = sorted(ROOT.glob(f"{depth}/{name}"), key=lambda p: len(str(p)))
        if hits:
            return hits[0]
    raise FileNotFoundError(f"{name} not found under {ROOT}")


def stage(name, fn):
    path = OUT / f"{name}.json"
    if path.exists():
        print(f"[{name}] cached")
        return json.loads(path.read_text())
    t = time.time()
    res = fn()
    path.write_text(json.dumps(res, indent=1, default=str))
    print(f"[{name}] {time.time() - t:.0f}s")
    return res


TRAIN = str(find("train.parquet"))
KEYMAP = load_keymap(str(POOL_DIR))
TRUTH = lambda ik: KEYMAP.get(ik, ik)  # noqa: E731
LIB = remap_keys(load_library(TRAIN, struct_mass=CFG.struct_mass), KEYMAP)
POOL, INFO = load_pool(str(POOL_DIR), drop_e180=True)


def cohort(names):
    rows = audit.load_cohorts(str(VAL_DIR), names)
    mols = [(mid, ik, sub) for mid, ik, sub, _, _ in rows]
    bans = {mid: audit.ban_mask(LIB, br, bk, KEYMAP) for mid, _, _, br, bk in rows}
    return mols, bans


C2, C2_BAN = cohort(("C2", "C2_hard"))
C1, C1_BAN = cohort(("C1_npx",))
print(f"C2 ∪ C2_hard {len(C2)} | C1_npx {len(C1)} | pool r1b {len(POOL):,} | library {len(LIB):,}")

# %% [markdown]
# ## Banks + featuriser parity

# %%
BANK = {}
PARITY = {}
for kind, (ckdir, bdirs) in BANKS.items():
    paths, bits, ref = fpnet.find_bank_files(kind, str(ckdir), bits_dirs=[str(b) for b in bdirs])
    BANK[kind] = fpnet.load_bank(kind, paths, bits)
    r = fpnet.parity_reference(kind, ref)
    PARITY[kind] = None if r is None else f"{fpnet.featuriser_parity(BANK[kind].feat, *r)}/{len(r[0])}"
    print(kind, BANK[kind].describe(), "parity", PARITY[kind])

# %% [markdown]
# ## R3.audit (own on C2 ∪ C2_hard) and the reported-only cells

# %%
RES = {}
for kind, tag in (("own", "own"), ("ahmed", "full1")):
    for cname, mols, bans in (("c2", C2, C2_BAN), ("c1", C1, C1_BAN)):
        rows = stage(f"{tag}_{cname}", lambda: audit.fp_discrimination(mols, LIB, POOL, TRUTH, BANK[kind], CFG,
                                                                        bans=bans))
        RES[f"{tag}_{cname}"] = audit.summarize_fp(rows, CFG.topn)
        print(tag, cname, json.dumps(RES[f"{tag}_{cname}"]))

# %% [markdown]
# ## Verdict (pre-registered)

# %%
g = RES["own_c2"]
print(f"R3.audit own C2∪C2_hard: n {g['n']} (in range {g['n_in_range']}); MRR@25 {g['mrr_before']:.4f} -> "
      f"{g['mrr_after']:.4f} (Δ {g['delta']:+.4f}, bar +0.02); up {g['up']} / down {g['down']}; reach {g['reach']:.3f}; "
      f"f.z-only MRR {g['fz_only_mrr']:.4f}, top-1 {g['fz_top1']:.3f}")
for k in ("full1_c2", "own_c1", "full1_c1"):
    r = RES[k]
    print(f"  (reported) {k}: Δ {r['delta']:+.4f} ({r['mrr_before']:.4f} -> {r['mrr_after']:.4f}), up {r['up']} / "
          f"down {r['down']}, f.z-only MRR {r['fz_only_mrr']:.4f}")
print(f"  {'PASS' if g['pass'] else 'FAIL'}  R3.audit (own, C2 ∪ C2_hard)")
(OUT / "verdicts.json").write_text(json.dumps(dict(verdict=g["pass"], results=RES, parity=PARITY,
                                                   total_s=round(time.time() - T0, 1)), indent=1, default=str))
